import React, { useState, useEffect, useRef } from 'react';
import { Flow } from 'flow-sdk';
import { DesignerCard } from './components/DesignerCard';
import { DiscussionLog } from './components/DiscussionLog';
import { ResultPanel } from './components/ResultPanel';
import { SectionLabel, PillButton, FieldDropdown, TextInput } from './components/Primitives';

type Phase = 'input' | 'discussing' | 'ready';

interface DesignerLine {
  designerId: number;
  text: string;
}

export default function App() {
  const [phase, setPhase] = useState<Phase>('input');
  const [userInput, setUserInput] = useState('');
  const [aspectRatio, setAspectRatio] = useState<'1:1' | '16:9' | '9:16' | '4:3' | '3:4'>('16:9');
  const [model, setModel] = useState('🍌 Nano Banana Pro');
  const [discussionLines, setDiscussionLines] = useState<DesignerLine[]>([]);
  const [finalPrompt, setFinalPrompt] = useState('');
  const [isGeneratingImage, setIsGeneratingImage] = useState(false);
  const [generatedImage, setGeneratedImage] = useState<{base64: string, mimeType: string} | null>(null);
  const [error, setError] = useState<string | null>(null);

  // Global CSS Injection
  useEffect(() => {
    const id = 'flow-design-system-css';
    if (document.getElementById(id)) return;
    const style = document.createElement('style');
    style.id = id;
    style.textContent = `
      .dark-scrollbar { scrollbar-width: thin; scrollbar-color: #595959 transparent; }
      .dark-scrollbar::-webkit-scrollbar { width: 6px; }
      .dark-scrollbar::-webkit-scrollbar-track { background: transparent; }
      .dark-scrollbar::-webkit-scrollbar-thumb { background: #595959; border-radius: 9999px; }
      @keyframes fade-in-up { from { opacity: 0; transform: translateY(10px); } to { opacity: 1; transform: translateY(0); } }
      .animate-fade-in-up { animation: fade-in-up 0.4s ease-out forwards; }
      html, body, #root { margin: 0; padding: 0; width: 100%; height: 100%; background: #0e0e0e; color: white; font-family: 'Google Sans Text', sans-serif; }
    `;
    document.head.appendChild(style);
  }, []);

  const startRoundtable = async () => {
    if (!userInput.trim()) return;

    setPhase('discussing');
    setDiscussionLines([]);
    setError(null);

    try {
      const { text } = await Flow.generate.text(
        `User Idea: "${userInput}"

        Act as a panel of 5 elite graphic designers (100 years combined exp) discussing this idea. 
        1. THE VISIONARY: Mood and concept.
        2. THE COMPOSITOR: Layout and hierarchy.
        3. THE COLORIST: Palette and lighting.
        4. THE TECHNICAL LEAD: Texture and detail.
        5. THE CRITIC: Final polish.

        Output MUST follow this format exactly:
        [1] (text from Visionary)
        [2] (text from Compositor)
        [3] (text from Colorist)
        [4] (text from Technical Lead)
        [5] (text from Critic)
        ---FINAL PROMPT---
        (The ultimate, detailed, high-level AI prompt)
        `,
        { 
          systemInstruction: "You are the moderator of the Elite Designer Collective. Your goal is to produce the world's best graphic design prompts through rigorous simulated discussion.",
          thinkingLevel: 'high'
        }
      );

      // Parse the output
      const sections = text.split('---FINAL PROMPT---');
      const discussionPart = sections[0];
      const promptPart = sections[1]?.trim() || "Elite professional design, ultra high definition.";

      const lines = discussionPart.match(/\[(\d)\]\s*(.*?)(?=\s*\[|$)/gs);
      const parsedLines: DesignerLine[] = (lines || []).map(line => {
        const idMatch = line.match(/\[(\d)\]/);
        const textMatch = line.replace(/\[\d\]/, '').trim();
        return { designerId: parseInt(idMatch?.[1] || '1'), text: textMatch };
      });

      // Simulate typing/discussion flow
      for (let i = 0; i < parsedLines.length; i++) {
        await new Promise(r => setTimeout(r, 1200));
        setDiscussionLines(prev => [...prev, parsedLines[i]]);
      }

      await new Promise(r => setTimeout(r, 800));
      setFinalPrompt(promptPart);
      setPhase('ready');
    } catch (err) {
      setError('The collective is unavailable. Please try again.');
      setPhase('input');
    }
  };

  const handleGenerateImage = async () => {
    setIsGeneratingImage(true);
    setError(null);
    try {
      const result = await Flow.generate.image({
        prompt: finalPrompt,
        aspectRatio,
        modelDisplayName: model
      });
      setGeneratedImage(result);
    } catch (err) {
      setError('Image generation failed.');
    } finally {
      setIsGeneratingImage(false);
    }
  };

  return (
    <div className="flex h-full w-full bg-[#0e0e0e] overflow-hidden">
      {/* Left Settings Panel */}
      <div className="w-[300px] h-full border-r border-[rgba(218,220,224,0.15)] flex flex-col justify-between px-[10px] py-[12px] shrink-0">
        <div className="flex flex-col gap-[24px] w-full">
          <div className="flex flex-col gap-2">
            <SectionLabel>Core Concept</SectionLabel>
            <TextInput 
              value={userInput} 
              onChange={setUserInput} 
              placeholder="E.g., A minimalist poster for a jazz festival in Tokyo..." 
            />
          </div>

          <div className="flex flex-col gap-2">
            <SectionLabel>Configuration</SectionLabel>
            <div className="flex flex-col gap-1.5">
              <FieldDropdown 
                label="Aspect Ratio" 
                value={aspectRatio} 
                options={['1:1', '16:9', '9:16', '4:3', '3:4']} 
                onChange={(v) => setAspectRatio(v as any)} 
              />
              <FieldDropdown 
                label="Creative Model" 
                value={model} 
                options={['🍌 Nano Banana Pro', '🍌 Nano Banana 2', '🍌 Nano Banana 2 Lite']} 
                onChange={setModel} 
              />
            </div>
          </div>
        </div>

        <div className="flex flex-col gap-1.5 pt-4">
          <PillButton 
            variant="solid" 
            onClick={startRoundtable}
            icon={<span className="material-symbols-outlined text-[18px]">psychology</span>}
            disabled={phase === 'discussing'}
          >
            {phase === 'discussing' ? 'Refining...' : 'Start Collective Review'}
          </PillButton>
        </div>
      </div>

      {/* Main Workspace */}
      <div className="flex-1 h-full overflow-y-auto dark-scrollbar flex flex-col p-8 gap-8 items-center">
        {phase === 'input' && !generatedImage && (
          <div className="max-w-xl w-full text-center mt-20 animate-fade-in-up">
            <span className="material-symbols-outlined text-6xl text-white/20 mb-4">diamond</span>
            <h1 className="text-2xl font-medium mb-2 tracking-tight">The Elite Designer Collective</h1>
            <p className="text-white/40 text-sm leading-relaxed">
              Input your raw concept on the left. Five specialist designers with a century of combined expertise will critique, polish, and synthesize your idea into an elite AI generation prompt.
            </p>
          </div>
        )}

        {(phase === 'discussing' || phase === 'ready') && (
          <div className="w-full max-w-4xl flex flex-col gap-8">
            {/* Designer Row */}
            <div className="grid grid-cols-5 gap-4">
              {[1, 2, 3, 4, 5].map(id => (
                <DesignerCard 
                  key={id} 
                  id={id} 
                  isActive={discussionLines.some(l => l.designerId === id)}
                  isSpeaking={discussionLines.length > 0 && discussionLines[discussionLines.length - 1].designerId === id && phase === 'discussing'}
                />
              ))}
            </div>

            {/* Discussion Log */}
            <DiscussionLog lines={discussionLines} isComplete={phase === 'ready'} />

            {/* Final Prompt & Preview */}
            {phase === 'ready' && (
              <div className="animate-fade-in-up">
                <ResultPanel 
                  prompt={finalPrompt} 
                  onGenerate={handleGenerateImage}
                  isGenerating={isGeneratingImage}
                  image={generatedImage}
                  error={error}
                />
              </div>
            )}
          </div>
        )}
      </div>
    </div>
  );
}

import React, { useState, useRef, useEffect } from 'react';

export const SectionLabel: React.FC<{ children: React.ReactNode }> = ({ children }) => (
  <div className="flex items-center px-2">
    <span className="text-[11px] font-medium text-[rgba(218,220,224,0.9)] tracking-[0.1px] uppercase">
      {children}
    </span>
  </div>
);

export const PillButton: React.FC<{
  icon?: React.ReactNode; 
  children: React.ReactNode;
  variant?: 'filled' | 'outline' | 'solid'; 
  onClick?: () => void;
  disabled?: boolean;
}> = ({ icon, children, variant = 'filled', onClick, disabled }) => {
  const base = 'flex items-center gap-2 justify-center w-full h-[34px] rounded-xl font-medium tracking-[0.1px] transition-all cursor-pointer disabled:opacity-50 disabled:cursor-not-allowed';
  const variants: Record<string, string> = {
    filled: 'bg-[#969696] hover:bg-[#a6a6a6] active:bg-[#868686] text-black text-[11px] px-4 py-1 select-none',
    outline: 'border border-[#595959] hover:bg-white/5 active:bg-white/10 backdrop-blur-[40px] text-[12px] px-4 py-2 text-white select-none',
    solid: 'bg-white hover:bg-gray-200 active:bg-gray-300 text-black text-[12px] px-4 py-2 select-none',
  };
  return (
    <button className={`${base} ${variants[variant]}`} onClick={onClick} disabled={disabled}>
      {icon && <span className="flex items-center justify-center w-5 h-5">{icon}</span>}
      <span>{children}</span>
    </button>
  );
};

export const FieldDropdown: React.FC<{
  label: string; value: string; options: string[];
  onChange: (val: string) => void; className?: string;
}> = ({ label, value, options, onChange, className = '' }) => {
  const [isOpen, setIsOpen] = useState(false);
  const ref = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const handler = (e: MouseEvent) => { if (ref.current && !ref.current.contains(e.target as Node)) setIsOpen(false); };
    document.addEventListener('mousedown', handler);
    return () => document.removeEventListener('mousedown', handler);
  }, []);

  return (
    <div ref={ref} className={`relative ${className}`}>
      <button type="button" onClick={() => setIsOpen(!isOpen)}
        className="w-full text-left border border-[#595959] hover:border-[#7a7a7a] transition-colors rounded-xl flex flex-col gap-0.5 justify-center pb-2 pl-2.5 pr-1 pt-[5px] select-none focus:outline-none h-[49px]">
        <p className="text-[11px] font-medium text-[rgba(255,255,255,0.35)] tracking-[0.1px]">{label}</p>
        <div className="flex items-center justify-between">
          <span className="text-[11px] font-medium text-white tracking-[0.1px]">{value}</span>
          <span className={`material-symbols-outlined text-[16px] text-[rgba(218,220,224,0.5)] mr-1 transition-transform ${isOpen ? 'rotate-180' : ''}`}>keyboard_arrow_down</span>
        </div>
      </button>
      {isOpen && (
        <div className="absolute z-50 top-[calc(100%+4px)] left-0 w-full bg-[#0e0e0e] border border-[#595959] rounded-xl overflow-hidden shadow-xl backdrop-blur-md animate-fade-in-up origin-top">
          <div className="max-h-40 overflow-y-auto dark-scrollbar">
            {options.map((opt) => (
              <button key={opt} type="button"
                className={`w-full text-left px-2.5 py-2 text-[11px] font-medium tracking-[0.1px] hover:bg-[#1a1a1a] transition-colors ${value === opt ? 'bg-[#1a1a1a] text-white' : 'text-[rgba(218,220,224,0.9)]'}`}
                onClick={() => { onChange(opt); setIsOpen(false); }}>
                {opt}
              </button>
            ))}
          </div>
        </div>
      )}
    </div>
  );
};

export const TextInput: React.FC<{
  value: string; onChange: (val: string) => void; placeholder?: string;
}> = ({ value, onChange, placeholder }) => (
  <textarea 
    value={value} 
    onChange={(e) => onChange(e.target.value)} 
    placeholder={placeholder}
    className="border border-[#595959] hover:border-[#7a7a7a] focus:border-[#969696] rounded-xl w-full h-[120px] px-3 py-2.5 resize-none bg-transparent text-[12px] font-medium text-white placeholder-[rgba(218,220,224,0.4)] tracking-[0.1px] focus:outline-none transition-colors" 
  />
);

import React from 'react';

const DESIGNERS = [
  { id: 1, name: 'Visionary', icon: 'visibility', color: 'text-purple-400' },
  { id: 2, name: 'Compositor', icon: 'grid_view', color: 'text-blue-400' },
  { id: 3, name: 'Colorist', icon: 'palette', color: 'text-red-400' },
  { id: 4, name: 'Technical', icon: 'architecture', color: 'text-green-400' },
  { id: 5, name: 'Critic', icon: 'verified', color: 'text-amber-400' },
];

export const DesignerCard: React.FC<{ id: number; isActive: boolean; isSpeaking: boolean }> = ({ id, isActive, isSpeaking }) => {
  const d = DESIGNERS[id - 1];

  return (
    <div className={`flex flex-col items-center gap-2 transition-all duration-500 ${isActive ? 'opacity-100 scale-100' : 'opacity-30 scale-95'}`}>
      <div className={`relative w-16 h-16 rounded-full flex items-center justify-center bg-white/5 border ${isSpeaking ? 'border-white animate-pulse' : 'border-white/10'}`}>
        <span className={`material-symbols-outlined text-2xl ${d.color}`}>
          {d.icon}
        </span>
        {isSpeaking && (
          <div className="absolute -bottom-1 -right-1 w-4 h-4 bg-green-500 rounded-full border-2 border-[#0e0e0e]" />
        )}
      </div>
      <div className="flex flex-col items-center">
        <span className="text-[10px] font-bold uppercase tracking-wider text-white/80">{d.name}</span>
        <span className="text-[9px] text-white/40">Designer 0{id}</span>
      </div>
    </div>
  );
};

import React, { useEffect, useRef } from 'react';

interface DesignerLine {
  designerId: number;
  text: string;
}

const DESIGNERS = [
  { id: 1, name: 'The Visionary', color: 'text-purple-400' },
  { id: 2, name: 'The Compositor', color: 'text-blue-400' },
  { id: 3, name: 'The Colorist', color: 'text-red-400' },
  { id: 4, name: 'The Technical Lead', color: 'text-green-400' },
  { id: 5, name: 'The Critic', color: 'text-amber-400' },
];

export const DiscussionLog: React.FC<{ lines: DesignerLine[]; isComplete: boolean }> = ({ lines, isComplete }) => {
  const bottomRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    bottomRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [lines]);

  return (
    <div className="w-full bg-white/5 border border-white/10 rounded-2xl p-6 min-h-[200px] max-h-[400px] overflow-y-auto dark-scrollbar flex flex-col gap-4">
      {lines.length === 0 && (
        <div className="flex-1 flex items-center justify-center text-white/20 italic text-sm">
          Awaiting initialization...
        </div>
      )}
      {lines.map((line, idx) => {
        const d = DESIGNERS[line.designerId - 1];
        return (
          <div key={idx} className="flex flex-col gap-1 animate-fade-in-up">
            <div className="flex items-center gap-2">
              <span className={`text-[11px] font-bold uppercase tracking-widest ${d.color}`}>{d.name}</span>
              <div className="h-[1px] flex-1 bg-white/5" />
            </div>
            <p className="text-[13px] leading-relaxed text-white/70 pl-2 border-l border-white/10 ml-1">
              {line.text}
            </p>
          </div>
        );
      })}
      {isComplete && (
        <div className="pt-4 flex items-center justify-center gap-2 text-green-400 animate-fade-in-up">
          <span className="material-symbols-outlined text-sm">check_circle</span>
          <span className="text-[11px] font-bold uppercase tracking-tighter">Consensus Reached</span>
        </div>
      )}
      <div ref={bottomRef} />
    </div>
  );
};

import React, { useState } from 'react';
import { PillButton } from './Primitives';
import { Flow } from 'flow-sdk';

export const ResultPanel: React.FC<{
  prompt: string;
  onGenerate: () => void;
  isGenerating: boolean;
  image: { base64: string; mimeType: string } | null;
  error: string | null;
}> = ({ prompt, onGenerate, isGenerating, image, error }) => {
  const [copyStatus, setCopyStatus] = useState('Copy Prompt');

  const handleCopy = () => {
    navigator.clipboard.writeText(prompt);
    setCopyStatus('Copied!');
    setTimeout(() => setCopyStatus('Copy Prompt'), 2000);
  };

  const handleDownload = async () => {
    if (!image) return;
    await Flow.download({
      base64: image.base64,
      mimeType: image.mimeType,
      filename: `elite-design-${Date.now()}.png`
    });
  };

  return (
    <div className="w-full flex flex-col gap-6">
      {/* Prompt Card */}
      <div className="bg-[#1a1a1a] border border-[#595959] rounded-2xl overflow-hidden">
        <div className="px-5 py-3 border-b border-[#595959] flex justify-between items-center bg-white/5">
          <span className="text-[11px] font-bold uppercase tracking-widest text-white/50">Elite Synthetic Prompt</span>
          <button 
            onClick={handleCopy}
            className="text-[10px] text-white/40 hover:text-white transition-colors uppercase font-bold"
          >
            {copyStatus}
          </button>
        </div>
        <div className="p-5">
          <p className="text-sm italic text-white/80 leading-relaxed font-mono">
            {prompt}
          </p>
        </div>
      </div>

      {/* Action Area */}
      <div className="flex flex-col items-center gap-6">
        <div className="w-64">
          <PillButton 
            variant="solid" 
            onClick={onGenerate}
            disabled={isGenerating}
            icon={<span className="material-symbols-outlined text-[18px]">auto_awesome</span>}
          >
            {isGenerating ? 'Forging Artwork...' : 'Generate Elite Visual'}
          </PillButton>
        </div>

        {error && (
          <div className="text-red-400 text-xs bg-red-400/10 px-4 py-2 rounded-lg border border-red-400/20">
            {error}
          </div>
        )}

        {isGenerating && (
          <div className="flex flex-col items-center gap-4 mt-4">
            <div className="w-12 h-12 border-4 border-white/10 border-t-white rounded-full animate-spin" />
            <span className="text-xs text-white/40 uppercase tracking-widest">Translating high-level concepts to pixels...</span>
          </div>
        )}

        {image && !isGenerating && (
          <div className="w-full max-w-2xl bg-white/5 p-2 rounded-2xl border border-white/10 animate-fade-in-up">
            <div className="relative group">
              <img 
                src={`data:${image.mimeType};base64,${image.base64}`} 
                alt="Generated Elite Design"
                className="w-full h-auto rounded-xl shadow-2xl"
              />
              <div className="absolute inset-0 bg-black/60 opacity-0 group-hover:opacity-100 transition-opacity flex items-center justify-center gap-4 rounded-xl">
                 <PillButton variant="outline" onClick={handleDownload} icon={<span className="material-symbols-outlined text-[18px]">download</span>}>
                  Download Asset
                 </PillButton>
              </div>
            </div>
            <div className="p-4 flex justify-between items-center">
              <span className="text-[10px] font-medium text-white/30 uppercase">Masterpiece Output v1.0</span>
              <span className="text-[10px] font-medium text-white/30 uppercase italic">Refined by the Collective</span>
            </div>
          </div>
        )}
      </div>
    </div>
  );
};
